  choices = $EXPL$["Any company that has issued debt securities regardless of its size or listing status","Only companies that are listed on the New York Stock Exchange for trading","A company with Section 12 registered securities or a registered 1933 Act public offering","Only companies whose annual revenues exceed the $100 million reporting threshold"]$EXPL$::jsonb,
